import { AggregateRoot, DomainEvent, Id } from '@Architecture/Domain';

/**
 * An invitation to a group, as the domain keeps it (conventions/domain.yaml, feature 3): a link generated by the domain,
 * whose id is what the link carries, so that whoever holds it may join. It is an aggregate of its own, not a part of the
 * Group: it is read by people who are not members, used any number of times, and changes nothing of the group when it
 * is created (the storm's first hot spot). It is never changed after its creation, so it has no store-side version.
 */
export class Invitation extends AggregateRoot {
  readonly #groupId: string;
  readonly #invitedBy: string;
  readonly #createdAt: string;

  private constructor(id: Id, groupId: string, invitedBy: string, createdAt: string, version: number) {
    super(id, version);
    this.#groupId = groupId;
    this.#invitedBy = invitedBy;
    this.#createdAt = createdAt;
  }

  /** The group the invitation is to. */
  get groupId(): string {
    return this.#groupId;
  }

  /**
   * A creation: the identity is generated here (DOMAIN-IDENTITY) and is long and random (a UUID, 122 random bits), so it is
   * the only proof a joiner needs. The creation records InvitationCreated. Pure: the time is `now`. Named `issue` here
   * (not `create`, Account's, nor `register`, Group's): the inventory matches a behaviour by its name, so each aggregate's creation has a name of its own.
   */
  static issue({ groupId, invitedBy }: InvitationDraft, now: Date): Invitation {
    const id = Id.generate();
    const at = now.toISOString();
    const invitation = new Invitation(id, groupId, invitedBy, at, 0);
    invitation.record(InvitationCreatedEvent.set({ invitationId: id.value, groupId, invitedBy, at }));
    return invitation;
  }

  /** The invitation as the store keeps it. Records nothing; throws on a snapshot that is not an invitation. */
  static fromSnapshot(snapshot: InvitationSnapshot): Invitation {
    if (!snapshot.id || !snapshot.groupId || !snapshot.invitedBy) {
      throw new Error(`The invitation ${snapshot.id} is corrupted: it has no group or no inviter`);
    }
    return new Invitation(new Id(snapshot.id), snapshot.groupId, snapshot.invitedBy, snapshot.createdAt, 0);
  }

  toSnapshot(): InvitationSnapshot {
    return {
      id: this._id.value,
      groupId: this.#groupId,
      invitedBy: this.#invitedBy,
      createdAt: this.#createdAt,
    };
  }
}

/** What a creation gives the aggregate: the group, and the member who invites. */
export interface InvitationDraft {
  readonly groupId: string;
  readonly invitedBy: string;
}

/** An invitation as the store keeps it. */
export interface InvitationSnapshot {
  readonly id: string;
  readonly groupId: string;
  readonly invitedBy: string;
  readonly createdAt: string;
}

export type InvitationCreatedPayload = { invitationId: string; groupId: string; invitedBy: string; at: string };

/**
 * The fact of an invitation (feature 3): who made it, for which group, and when. It is made durable with the invitation
 * and published after the commit; nothing subscribes to it yet.
 */
export class InvitationCreatedEvent extends DomainEvent<InvitationCreatedPayload> {}
